package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.*;
/** Pending native inputs and once-only output counters share one bounded server save, never block/client item NBT. */
public final class MillingEvidence {
 public record Cell(String dimension,long position){public Cell{if(dimension==null||dimension.length()>96||!dimension.matches("[a-z0-9_.-]+:[a-z0-9_./-]+"))throw new IllegalArgumentException("Invalid milling site");}}
 public record Job(UUID source,UUID owner,int initial,int remaining){public Job{Objects.requireNonNull(source);Objects.requireNonNull(owner);if(initial<1||initial>64||remaining<1||remaining>initial)throw new IllegalArgumentException("Invalid native milling input batch");}}
 private final Map<Cell,Job> jobs=new HashMap<>();private final ProfessionEvidence outputs;
 public MillingEvidence(){outputs=new ProfessionEvidence(Profession.ENGINEER,Set.of("milled_flour"));}
 private MillingEvidence(ProfessionEvidence outputs){this.outputs=outputs;}
 public List<Map.Entry<Cell,Job>> jobsFor(UUID owner,int limit){if(limit<1||limit>16)throw new IllegalArgumentException("Inspection is bounded1..16");return jobs.entrySet().stream().filter(e->e.getValue().owner().equals(owner)).sorted(Comparator.comparing(e->e.getKey().dimension()+"/"+e.getKey().position())).limit(limit).map(e->Map.entry(e.getKey(),e.getValue())).toList();}
 public Optional<Job> job(Cell cell){return Optional.ofNullable(jobs.get(cell));}
 public void invalidate(Cell cell){jobs.remove(cell);}
 public boolean start(Cell cell,UUID source,UUID player,int amount){if(jobs.size()>=4096||jobs.values().stream().anyMatch(j->j.source().equals(source)))return false;jobs.put(cell,new Job(source,player,amount,amount));return true;}
 public boolean advance(Cell cell,Job expected,int amount){if(amount<0||amount>3)throw new IllegalArgumentException("Unverified native wheat yield");if(!expected.equals(jobs.get(cell)))return false;if(expected.remaining()==1)jobs.remove(cell);else jobs.put(cell,new Job(expected.source(),expected.owner(),expected.initial(),expected.remaining()-1));return amount>0&&outputs.record(expected.owner(),ProfessionRank.APPRENTICE,"milled_flour",amount,"milling/"+expected.source()+"/"+(expected.initial()-expected.remaining()+1));}
 public int count(UUID owner){return outputs.count(owner,ProfessionRank.APPRENTICE,"milled_flour");}
 public CompoundTag save(){var tag=new CompoundTag();tag.putInt("schema",1);tag.put("outputs",outputs.save());var rows=new ListTag();jobs.entrySet().stream().sorted(Comparator.comparing(e->e.getKey().dimension()+"/"+e.getKey().position())).forEach(e->{var r=new CompoundTag();r.putString("dimension",e.getKey().dimension());r.putLong("position",e.getKey().position());r.putUUID("source",e.getValue().source());r.putUUID("owner",e.getValue().owner());r.putInt("initial",e.getValue().initial());r.putInt("remaining",e.getValue().remaining());rows.add(r);});tag.put("jobs",rows);return tag;}
 public static MillingEvidence load(CompoundTag tag){if(!tag.getAllKeys().equals(Set.of("schema","outputs","jobs"))||!tag.contains("schema",Tag.TAG_INT)||tag.getInt("schema")!=1||!tag.contains("outputs",Tag.TAG_COMPOUND)||!(tag.get("jobs") instanceof ListTag rows)||rows.size()>4096||!rows.isEmpty()&&rows.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Invalid milling evidence schema");var result=new MillingEvidence(ProfessionEvidence.load(tag.getCompound("outputs"),Profession.ENGINEER,Set.of("milled_flour")));Set<UUID> sources=new HashSet<>();for(var value:rows){var r=(CompoundTag)value;if(!r.getAllKeys().equals(Set.of("dimension","position","source","owner","initial","remaining"))||!r.contains("dimension",Tag.TAG_STRING)||!r.contains("position",Tag.TAG_LONG)||!r.hasUUID("source")||!r.hasUUID("owner")||!r.contains("initial",Tag.TAG_INT)||!r.contains("remaining",Tag.TAG_INT))throw new IllegalArgumentException("Invalid milling job");var cell=new Cell(r.getString("dimension"),r.getLong("position"));var job=new Job(r.getUUID("source"),r.getUUID("owner"),r.getInt("initial"),r.getInt("remaining"));if(result.jobs.put(cell,job)!=null||!sources.add(job.source()))throw new IllegalArgumentException("Duplicate milling source/site");}return result;}
}
